ALTER TABLE "companions" DROP CONSTRAINT "companion_rules";--> statement-breakpoint
ALTER TABLE "companions" ADD CONSTRAINT "companion_rules" CHECK ("companions"."species" in ('dragon','fox','phoenix','capybara','rabbit','cat','wolf','unicorn','ape','tortoise') and "companions"."stage" between 0 and 4 and (("companions"."stage"=0 and "companions"."display_stage"=0) or ("companions"."stage">0 and "companions"."display_stage" between 1 and "companions"."stage")) and "companions"."appearance" in ('animal','human') and "companions"."human_style" in ('boy','girl') and ("companions"."appearance"='animal' or ("companions"."species" in ('fox','phoenix','cat','wolf','ape','tortoise') and "companions"."display_stage">=3)) and ("companions"."species" not in ('ape','tortoise') or "companions"."human_style"='boy'));